import 'package:flutter/material.dart';
import 'package:flutter_overlay_window/flutter_overlay_window.dart';

void main() {
  runApp(const MyApp());
  }

  // Ponto de entrada da Janela Flutuante (A Bolha)
  @pragma("vm:entry-point")
  void overlayMain() {
    WidgetsFlutterBinding.ensureInitialized();
      runApp(
          const MaterialApp(
                debugShowCheckedModeBanner: false,
                      home: FloatingOverlayView(),
                          ),
                            );
                            }

                            class MyApp extends StatelessWidget {
                              const MyApp({super.key});

                                @override
                                  Widget build(BuildContext context) {
                                      return MaterialApp(
                                            debugShowCheckedModeBanner: false,
                                                  title: 'Uber Calc Helper',
                                                        theme: ThemeData(primarySwatch: Colors.blue),
                                                              home: const HomeScreen(),
                                                                  );
                                                                    }
                                                                    }

                                                                    // Tela principal do app
                                                                    class HomeScreen extends StatelessWidget {
                                                                      const HomeScreen({super.key});

                                                                        @override
                                                                          Widget build(BuildContext context) {
                                                                              return Scaffold(
                                                                                    appBar: AppBar(title: const Text('Uber Calc Flutuante')),
                                                                                          body: Center(
                                                                                                  child: Padding(
                                                                                                            padding: const EdgeInsets.all(20.0),
                                                                                                                      child: Column(
                                                                                                                                  mainAxisAlignment: MainAxisAlignment.center,
                                                                                                                                              children: [
                                                                                                                                                            const Text(
                                                                                                                                                                            'Conceda a permissão para ativar a bolha flutuante sobre outros apps.',
                                                                                                                                                                                            textAlign: TextAlign.center,
                                                                                                                                                                                                            style: TextStyle(fontSize: 16),
                                                                                                                                                                                                                          ),
                                                                                                                                                                                                                                        const SizedBox(height: 20),
                                                                                                                                                                                                                                                      ElevatedButton(
                                                                                                                                                                                                                                                                      onPressed: () async {
                                                                                                                                                                                                                                                                                        bool? status = await FlutterOverlayWindow.isPermissionGranted();
                                                                                                                                                                                                                                                                                                          if (status != true) {
                                                                                                                                                                                                                                                                                                                              await FlutterOverlayWindow.requestPermission();
                                                                                                                                                                                                                                                                                                                                                } else {
                                                                                                                                                                                                                                                                                                                                                                    await FlutterOverlayWindow.showOverlay(
                                                                                                                                                                                                                                                                                                                                                                                          height: 90,
                                                                                                                                                                                                                                                                                                                                                                                                                width: 210,
                                                                                                                                                                                                                                                                                                                                                                                                                                      alignment: OverlayAlignment.topRight,
                                                                                                                                                                                                                                                                                                                                                                                                                                                            flag: OverlayFlag.defaultFlag,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  visibility: NotificationVisibility.visibilityPublic,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        positionGravity: PositionGravity.none,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              child: const Text('Ativar Bolha Flutuante'),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ],
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      // O Widget da Bolha Flutuante (Fica no canto superior)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      class FloatingOverlayView extends StatefulWidget {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const FloatingOverlayView({super.key});

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          @override
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            State<FloatingOverlayView> createState() => _FloatingOverlayViewState();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            class _FloatingOverlayViewState extends State<FloatingOverlayView> {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              // Valores de teste da corrida
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                double valorCorrida = 24.50;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  double distanciaKm = 6.2;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    double tempoMinutos = 15.0;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      @override
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        Widget build(BuildContext context) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            double ganhoPorKm = valorCorrida / distanciaKm;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                double ganhoPorHora = valorCorrida / (tempoMinutos / 60);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return Material(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          color: Colors.transparent,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                child: Container(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        padding: const EdgeInsets.all(8),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                decoration: BoxDecoration(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          color: Colors.black.withOpacity(0.9),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    borderRadius: BorderRadius.circular(10),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              border: Border.all(color: Colors.greenAccent, width: 1.5),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              child: Row(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        mainAxisSize: MainAxisSize.min,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  children: [
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              Column(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            crossAxisAlignment: CrossAxisAlignment.start,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          mainAxisAlignment: MainAxisAlignment.center,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        children: [
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        Text(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          "R\$ ${valorCorrida.toStringAsFixed(2)}",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            style: const TextStyle(color: Colors.white, fontSize: 11, fontWeight: FontWeight.bold),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            Text(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              "Km: R\$ ${ganhoPorKm.toStringAsFixed(2)}/km",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                style: const TextStyle(color: Colors.greenAccent, fontSize: 11, fontWeight: FontWeight.bold),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                Text(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  "Hora: R\$ ${ganhoPorHora.toStringAsFixed(0)}/h",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    style: const TextStyle(color: Colors.yellowAccent, fontSize: 11, fontWeight: FontWeight.bold),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ],
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const SizedBox(width: 8),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      GestureDetector(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    onTap: () async {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    await FlutterOverlayWindow.closeOverlay();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                child: const Icon(Icons.close, color: Colors.white70, size: 18),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ],
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          